const today = new Date();
// Format date as YYYY-MM-DD or find the Day Number to post
// E.g., Day 1 to 30 based on launch offset
// Here we extract the day_number matching the calendar sheet
const launchDate = new Date('2026-05-22'); // Set launch date
const timeDiff = today.getTime() - launchDate.getTime();
const dayDiff = Math.floor(timeDiff / (1000 * 3600 * 24)) + 1;

const activeDay = (dayDiff > 0 && dayDiff <= 30) ? dayDiff : 1;

// Filter calendar rows for the matching day
const matchingRow = $input.all().find(row => parseInt(row.json.day_number) === activeDay);

if (!matchingRow) {
  throw new Error(`No content found in calendar for day number: ${activeDay}`);
}

return matchingRow.json;

